h2{font-size:14pt;line-height:1.15;margin:16pt 0 6pt;border-bottom:0.4pt solid #888;padding-bottom:2pt}h3{font-size:11.5pt;margin:10pt 0 3pt}h4{font-size:10.5pt;margin:7pt 0 2pt}p{margin:0 0 7pt;text-align:justify;orphans:2;widows:2}
figure{margin:10pt 0 13pt;text-align:center;break-inside:avoid;page-break-inside:avoid}figure img{display:block;width:100%;max-height:245mm;object-fit:contain;margin:auto}figcaption{font-size:9pt;line-height:1.25;margin-top:4pt;text-align:left}table{border-collapse:collapse;width:100%;margin:9pt 0 12pt;font-size:8.1pt;line-height:1.2;break-inside:auto}caption{text-align:left;font-weight:700;font-size:9pt;margin-bottom:3pt}th,td{border:0.45pt solid #777;padding:3.5pt 4pt;vertical-align:top;text-align:left}thead{display:table-header-group}tr{break-inside:avoid;page-break-inside:avoid}.equation{font-family:'DejaVu Math','DejaVu Sans',sans-serif;text-align:center;margin:8pt 0;padding:5pt;border-top:0.4pt solid #aaa;border-bottom:0.4pt solid #aaa;font-size:11pt}.equation span{font-family:'DejaVu Serif',serif;font-size:9pt;font-weight:700;margin-right:8pt}.references-heading{page-break-before:always}.references{font-size:8.1pt;line-height:1.25;padding-left:24pt}.references li{padding-left:3pt;margin:0 0 3pt;break-inside:avoid}.missing-asset{border:0.5pt solid #b44;padding:18pt;color:#933}
